// D1 Normaliza a peça aprovada (vinda do fluxo C ou do mock). dry_run padrão = true.
const p = $input.first().json;
return [{ json: { ...p, dry_run: p.dry_run === false ? false : true } }];

// D2 Blotato = hub único. 1 peça aprovada -> 1 post por conta conectada (Blotato exige accountId por plataforma).
// dry_run é o padrão: só fica live se input.dry_run === false E env MKT_LIVE === 'true'. E os nós POST estão desativados.
const env = k => { try { return $env[k]; } catch (e) { return undefined; } };
const piece = $('Approved piece (input)').first().json;
const accs = ($input.first().json.items || []);
const live = piece.dry_run === false && String(env('MKT_LIVE') || '').toLowerCase() === 'true';
const PLAT = { instagram: 'instagram', tiktok: 'tiktok', youtube: 'youtube', facebook: 'facebook', linkedin: 'linkedin', threads: 'threads', twitter: 'twitter' };
const SLOTS = { linkedin: '08:00', twitter: '08:30', threads: '07:30', facebook: '12:30', instagram: '18:00', tiktok: '19:00', youtube: '17:00' }; // Brisbane UTC+10
const nextSlot = hhmm => { const base = new Date(Date.now() + 10 * 36e5).toISOString().slice(0, 10); let d = new Date(`${base}T${hhmm}:00+10:00`); while (d.getTime() < Date.now() + 10 * 60e3) d = new Date(d.getTime() + 864e5); return new Date(d.getTime() + 10 * 36e5).toISOString().slice(0, 19) + '+10:00'; };
const media = piece.media_urls || [];
return (piece.target_platforms || []).map(pl => {
  const platform = PLAT[pl] || pl; const acc = accs.find(a => a.platform === platform) || null; const v = (piece.platform_variants || {})[pl] || {};
  let target = { targetType: platform };
  if (platform === 'facebook') target.pageId = env('BLOTATO_FACEBOOK_PAGE_ID') || 'PENDENTE_PAGE_ID';
  if (platform === 'tiktok') target = { targetType: 'tiktok', privacyLevel: 'PUBLIC_TO_EVERYONE', disabledComments: false, disabledDuet: false, disabledStitch: false, isBrandedContent: false, isYourBrand: true, isAiGenerated: true, title: (v.title || '').slice(0, 90) };
  if (platform === 'youtube') target = { targetType: 'youtube', title: (v.title || piece.title || '').slice(0, 100), privacyStatus: 'public', shouldNotifySubscribers: true };
  if (platform === 'instagram') target = { targetType: 'instagram', mediaType: media.length ? 'reel' : undefined };
  const body = { post: { accountId: acc ? String(acc.id) : 'PENDENTE_ACCOUNT_' + platform, content: { text: v.text || piece.caption || '', mediaUrls: media, platform }, target }, scheduledTime: piece.publish_now ? undefined : nextSlot(SLOTS[platform] || '12:00') };
  const problems = [];
  if (!acc) problems.push('conta não conectada no Blotato');
  if (['tiktok', 'youtube', 'instagram'].includes(platform) && !media.length) problems.push('plataforma exige vídeo/imagem (mídia pendente)');
  return { json: { company_id: piece.company_id, piece_id: piece.id || null, provider: 'blotato', is_fallback: false, platform, account_id: acc ? String(acc.id) : null, dry_run: !live, body, problems } };
});

// D4 Resultado (dry-run ou live) -> linhas para mkt_distribution_jobs. Falhas vão para o fallback.
return $input.all().map(({ json: j }) => {
  const failed = !j.dry_run && (!!j.error || j.status === 'failed');
  return { json: { company_id: j.company_id, piece_id: j.piece_id, provider: j.provider, is_fallback: j.is_fallback, platform: j.platform, account_id: j.account_id,
    dry_run: j.dry_run, status: j.dry_run ? 'dry_run' : (failed ? 'failed' : (j.scheduledTime ? 'scheduled' : 'submitted')), provider_post_id: j.postSubmissionId || null,
    scheduled_for: j.body?.scheduledTime || null, request: j.body || {}, response: j.dry_run ? { note: 'DRY-RUN: nada foi enviado', problems: j.problems } : (j.response || {}), error: failed ? String(j.error || 'failed') : null, needs_fallback: failed } };
});

// D6 Fallback (só se o Blotato falhar): Ayrshare aceita 1 chamada com várias plataformas; Outstand por conta.
const failed = $input.all().map(i => i.json).filter(j => j.needs_fallback);
if (!failed.length) return [];
const piece = $('Approved piece (input)').first().json;
const platforms = [...new Set(failed.map(f => f.platform))];
return [{ json: { provider: 'ayrshare', dry_run: true, body: { post: piece.caption, platforms, mediaUrls: piece.media_urls || [] }, outstand_alt: platforms.map(p => ({ platform: p, text: (piece.platform_variants || {})[p]?.text })) } }];
